#include <stdio.h>
#include <string.h>
#include <ctype.h>

static const char *SYMS[] = {
    "M", "CM", "D", "CD", "C", "XC", "L", "XL",
    "X", "IX", "V", "IV", "I"
};
static const int VALS[] = {
    1000, 900, 500, 400, 100, 90, 50, 40,
    10, 9, 5, 4, 1
};

int main(int argc, char *argv[]) {
    if (argc < 2) {
        puts("INVALID");
        return 0;
    }
    const char *input = argv[1];
    size_t len = strlen(input);
    if (len == 0 || len > 63) {
        puts("INVALID");
        return 0;
    }
    // Convert to uppercase copy
    char upper[64];
    for (size_t i = 0; i < len; ++i) {
        char c = input[i];
        if ('a' <= c && c <= 'z') c = c - ('a' - 'A');
        upper[i] = c;
    }
    upper[len] = '\0';

    int total = 0;
    size_t pos = 0; // position in upper string
    char built[256] = {0}; // will hold concatenated matched symbols
    size_t built_len = 0;

    for (size_t i = 0; i < sizeof(SYMS)/sizeof(SYMS[0]); ++i) {
        const char *sym = SYMS[i];
        size_t sym_len = strlen(sym);
        while (pos + sym_len <= len && strncmp(upper + pos, sym, sym_len) == 0) {
            total += VALS[i];
            // copy symbol to built string
            memcpy(built + built_len, sym, sym_len);
            built_len += sym_len;
            pos += sym_len;
        }
    }

    // After processing, the built string must exactly match the input (uppercase)
    if (pos == len && built_len == len && memcmp(built, upper, len) == 0) {
        printf("%d\n", total);
    } else {
        puts("INVALID");
    }
    return 0;
}
}
